
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_mn15_l_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_mn15_l", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.051969632030697e+00, -3.147312751642316e+00, -3.269869110047114e+00, -3.416743556949120e+00, -3.569658852400347e+00, -3.677395163031780e+00, -3.630494999054494e+00, -3.255568210967482e+00, -2.442772306310753e+00, -1.459435007999028e+00, -6.642057642449927e-01, -4.637269731961708e-01, -6.160082285045396e-01, -5.087555723706459e-01, -3.556842972047736e-01, -2.211382995090987e-01, -9.896795954490509e-02, -4.631989978639508e-02, -1.285089431210643e-02, -1.531562769557249e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


